INSERT INTO news_summaries(article_id, summary_text, summary_version, model_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/1'), '첫 적금은 무리하지 않는 금액으로 시작하고, 중도 해지하면 이자가 줄어든다는 점을 알아 둔다. 청년 정책 상품은 조건을 함께 확인한다.', 1, 'sample' WHERE NOT EXISTS (SELECT 1 FROM news_summaries WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/1') AND valid_to IS NULL);
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/1'), 1, '적금을 중도에 해지하면 어떻게 되나요?', '["이자가 크게 줄어든다", "이자가 두 배가 된다", "원금이 늘어난다", "아무 변화가 없다"]'::jsonb, 0, '기사에서 중도 해지하면 이자가 크게 줄어든다고 설명한다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/1'), 2, '첫 적금을 시작할 때 권하는 방법은?', '["한 달만 넣고 해지", "무리하지 않는 금액으로 시작", "가능한 최대 금액으로 시작", "대출을 받아 시작"]'::jsonb, 1, '무리하지 않는 금액으로 시작하는 것이 좋다고 했다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/1'), 3, '청년 정책 상품에 대해 기사가 말한 것은?', '["일반 상품보다 항상 불리하다", "가입이 금지되어 있다", "혜택이 클 수 있으니 조건을 확인한다", "누구나 조건 없이 가입한다"]'::jsonb, 2, '혜택이 클 수 있으니 조건을 함께 확인하라고 했다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
