INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/3', '샘플 데이터', '[샘플] 인플레이션이 내 지갑에 미치는 영향', '인플레이션은 물건과 서비스의 가격이 전반적으로 오르는 현상이다. 같은 돈으로 살 수 있는 물건이 줄어들기 때문에 돈의 가치가 떨어진다. 물가가 빠르게 오르면 중앙은행은 금리를 올려 소비와 대출을 줄이려 한다. 금리가 오르면 예금 이자는 늘지만 대출 이자 부담도 함께 커진다. 생활비 계획을 세울 때 물가 흐름을 함께 살펴보는 것이 도움이 된다.', '경제', now() - interval '3 hours') ON CONFLICT (source_url) DO NOTHING;
