INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/4', '샘플 데이터', '[샘플] 전세대출 받기 전에 확인할 세 가지', '전세대출은 전세 보증금을 마련하기 위해 받는 대출이다. 먼저 집주인이 실제 소유자인지 등기부등본으로 확인해야 한다. 다음으로 보증금을 돌려받지 못할 위험에 대비해 보증보험 가입이 가능한지 살핀다. 마지막으로 대출 금리와 상환 방식을 비교해 매달 낼 이자를 계산한다. 계약 전에 꼼꼼히 확인할수록 분쟁을 줄일 수 있다.', '부동산', now() - interval '4 hours') ON CONFLICT (source_url) DO NOTHING;
