INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/4'), 3, '대출 금리와 상환 방식을 비교하는 이유는?', '["집값을 올리려고", "보증금을 줄이려고", "등기를 바꾸려고", "매달 낼 이자를 계산하려고"]'::jsonb, 3, '매달 낼 이자를 계산하라고 했다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/5', '샘플 데이터', '[샘플] 신용대출, 한도보다 중요한 것', '신용대출은 담보 없이 개인의 신용을 바탕으로 받는 대출이다. 한도가 크게 나오더라도 필요한 만큼만 빌리는 것이 좋다. 금리가 변동형이면 시장 금리에 따라 매달 이자가 달라질 수 있다. 연체가 생기면 신용점수가 떨어져 다음 대출이 어려워진다. 상환 계획을 먼저 세우고 대출을 받는 습관이 중요하다.', '금융', now() - interval '5 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/5'), 6, 0, 4 WHERE NOT EXISTS (SELECT 1 FROM article_term_highlights WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/5') AND term_id = 6 AND position_start = 0);
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/5'), 8, 66, 68 WHERE NOT EXISTS (SELECT 1 FROM article_term_highlights WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/5') AND term_id = 8 AND position_start = 66);
INSERT INTO news_summaries(article_id, summary_text, summary_version, model_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/5'), '신용대출은 담보 없이 받는 대출로, 필요한 만큼만 빌리고 연체를 피하는 상환 계획이 중요하다.', 1, 'sample' WHERE NOT EXISTS (SELECT 1 FROM news_summaries WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/5') AND valid_to IS NULL);
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/6', '샘플 데이터', '[샘플] 목돈 만들기, 적금과 예금의 차이', '적금은 매달 돈을 나눠 넣고, 예금은 한 번에 맡기는 방식이다. 모아 둔 돈이 없다면 적금으로 목돈을 만드는 것이 현실적이다. 이미 목돈이 있다면 예금에 맡겨 이자를 받을 수 있다. 두 상품 모두 금리와 만기를 비교해 고르는 것이 기본이다. 비상금은 언제든 꺼낼 수 있는 통장에 따로 두는 것이 안전하다.', '저축', now() - interval '6 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6'), 8, 110, 112 WHERE NOT EXISTS (SELECT 1 FROM article_term_highlights WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6') AND term_id = 8 AND position_start = 110);
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6'), 10, 0, 2 WHERE NOT EXISTS (SELECT 1 FROM article_term_highlights WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6') AND term_id = 10 AND position_start = 0);
INSERT INTO news_summaries(article_id, summary_text, summary_version, model_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6'), '적금은 나눠서, 예금은 한 번에 맡기는 방식이다. 목돈이 없으면 적금이 현실적이고 비상금은 따로 둔다.', 1, 'sample' WHERE NOT EXISTS (SELECT 1 FROM news_summaries WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6') AND valid_to IS NULL);
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6'), 1, '적금과 예금의 차이로 맞는 것은?', '["적금은 나눠 넣고 예금은 한 번에 맡긴다", "적금은 한 번에 맡긴다", "예금은 매달 넣어야 한다", "둘은 같은 상품이다"]'::jsonb, 0, '적금은 매달 나눠 넣고 예금은 한 번에 맡긴다고 했다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6'), 2, '모아 둔 돈이 없을 때 기사가 권한 방법은?', '["비상금 쓰기", "적금으로 목돈 만들기", "예금에 한 번에 맡기기", "대출로 예금 들기"]'::jsonb, 1, '모아 둔 돈이 없다면 적금이 현실적이라고 했다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/6'), 3, '비상금은 어디에 두라고 했나요?', '["주식 계좌", "적금 계좌", "언제든 꺼낼 수 있는 통장", "장기 예금"]'::jsonb, 2, '언제든 꺼낼 수 있는 통장에 따로 두라고 했다.', '[1]'::jsonb, 'sample', 'sample' ON CONFLICT (article_id, quiz_order) DO NOTHING;
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/7', '샘플 데이터', '[샘플] 청년 지원 정책, 신청 전에 볼 것', '청년 지원 정책은 나이와 소득, 거주 지역에 따라 신청 조건이 다르다. 같은 이름의 사업이라도 지역마다 지원 내용이 다를 수 있다. 신청 기간을 놓치면 다음 해까지 기다려야 하는 경우가 많다. 필요한 서류를 미리 준비하면 신청 과정이 훨씬 수월하다. 정확한 내용은 담당 기관의 공고에서 확인한다.', '정책', now() - interval '7 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO news_summaries(article_id, summary_text, summary_version, model_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/7'), '청년 지원 정책은 나이·소득·지역에 따라 조건이 다르고 신청 기간이 정해져 있어 공고를 미리 확인해야 한다.', 1, 'sample' WHERE NOT EXISTS (SELECT 1 FROM news_summaries WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/7') AND valid_to IS NULL);
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/8', '샘플 데이터', '[샘플] 첫 월급 받기 전에 알아둘 돈 관리', '취업 후 첫 월급을 받으면 세금과 보험료가 빠진 금액이 들어온다. 먼저 고정 지출을 정리하고 남는 돈의 일부를 저축으로 돌린다. 적금이나 자동이체를 활용하면 저축을 꾸준히 이어가기 쉽다. 카드 사용액은 다음 달 월급에서 빠져나가므로 한도를 정해 두는 것이 좋다. 작은 금액이라도 비상금을 따로 모으는 습관이 도움이 된다.', '취업', now() - interval '8 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/8'), 10, 72, 74 WHERE NOT EXISTS (SELECT 1 FROM article_term_highlights WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/8') AND term_id = 10 AND position_start = 72);
INSERT INTO news_summaries(article_id, summary_text, summary_version, model_version) SELECT (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/8'), '첫 월급은 세금과 보험료를 뺀 금액이 들어오므로 고정 지출을 정리하고 자동이체로 저축을 이어가는 것이 좋다.', 1, 'sample' WHERE NOT EXISTS (SELECT 1 FROM news_summaries WHERE article_id = (SELECT id FROM news_articles WHERE source_url = 'local-sample://article/8') AND valid_to IS NULL);
